# show 4-connected components
seen=set(); comps=[]
for r,row in enumerate(grid):
 for c,x in enumerate(row):
  if x==4 and (r,c) not in seen:
   st=[(r,c)]; seen.add((r,c)); comp=[]
   while st:
    p=st.pop(); comp.append(p)
    for q in [(p[0]+1,p[1]),(p[0]-1,p[1]),(p[0],p[1]+1),(p[0],p[1]-1)]:
     if 0<=q[0]<10 and 0<=q[1]<19 and grid[q[0]][q[1]]==4 and q not in seen:
      seen.add(q);st.append(q)
   comps.append(comp)
[(len(x),(min(r for r,c in x),max(r for r,c in x),min(c for r,c in x),max(c for r,c in x))) for x in comps]
